UPDATE `creature_model_info` c JOIN `tmp_tailles_siege` t ON t.`DisplayID` = c.`DisplayID`
SET c.`BoundingRadius` = t.`BoundingRadius`, c.`CombatReach` = t.`CombatReach`
WHERE c.`BoundingRadius` = 0 AND c.`CombatReach` = 0;
DROP TEMPORARY TABLE `tmp_tailles_siege`;

-- 2. Galakras (72249) : a terre, il est surtout frappe par les PNJ allies et les tourelles ; sous
--    50 % de degats joueurs, Unit::Kill ne donne ni credit ni butin (meme cas que l Amalgame).
--    CREATURE_FLAG_EXTRA_NO_PLAYER_DAMAGE_REQ = 0x00200000.
UPDATE `creature_template` SET `flags_extra` = `flags_extra` | 0x00200000 WHERE `entry` = 72249;

-- 3. Loups des Chamans noirs (Darkfang 71921, Bloodclaw 71923) : les chamans montent dessus par
--    EnterVehicle (boss_korkron_dark_shaman.cpp, SummonMount) mais VehicleId etait 0 : le chaman
--    restait invoque DANS le modele du loup. VehicleId 25 chez LegionCore et pandaria_5.4.8
--    (siege 341 : passager ciblable).
UPDATE `creature_template` SET `VehicleId` = 25 WHERE `entry` IN (71921, 71923);

